-- mistri store layout: record-history, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_history_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_history_change" (
  id INTEGER PRIMARY KEY,
  write_id TEXT COLLATE BINARY NOT NULL,
  at TEXT NOT NULL,
  resource TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(resource AS BLOB)) <= 512),
  key_json TEXT COLLATE BINARY NOT NULL CHECK (json_valid(key_json) AND length(CAST(key_json AS BLOB)) <= 2048),
  kind TEXT NOT NULL CHECK (kind IN ('insert', 'update', 'delete')),
  changes_json TEXT NOT NULL CHECK (json_valid(changes_json) AND length(CAST(changes_json AS BLOB)) <= 262144),
  actor TEXT COLLATE BINARY NOT NULL,
  actor_name TEXT NOT NULL,
  via TEXT NOT NULL CHECK (via IN ('app', 'workbench', 'agent', 'api', 'form', 'system')),
  action TEXT NOT NULL
);
CREATE INDEX "__mistri_history_change_record" ON "__mistri_history_change" (resource, key_json, id);
CREATE INDEX "__mistri_history_change_at" ON "__mistri_history_change" (at);
